/**
 * Expo config plugin: signs Android release builds with the keystore that
 * Codemagic provides (codemagic.yaml → environment.android_signing), which it
 * exposes as CM_KEYSTORE_PATH / CM_KEYSTORE_PASSWORD / CM_KEY_ALIAS /
 * CM_KEY_PASSWORD. Without those variables (local builds, other CI) release
 * builds keep Expo's default debug signing, so nothing else changes.
 *
 * android/ is generated by `expo prebuild` and git-ignored, so the change has
 * to be applied here rather than edited into build.gradle.
 */
const { withAppBuildGradle } = require('@expo/config-plugins');

const MARKER = '// mercon: release signing from CM_KEYSTORE_*';

const RELEASE_CONFIG = `
        ${MARKER}
        if (System.getenv("CM_KEYSTORE_PATH")) {
            release {
                storeFile file(System.getenv("CM_KEYSTORE_PATH"))
                storePassword System.getenv("CM_KEYSTORE_PASSWORD")
                keyAlias System.getenv("CM_KEY_ALIAS")
                keyPassword System.getenv("CM_KEY_PASSWORD")
            }
        }`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    let gradle = mod.modResults.contents;
    if (gradle.includes(MARKER)) return mod;

    // 1. Add a `release` signing config inside `signingConfigs { ... }`.
    const signingBlock = /signingConfigs\s*\{/;
    if (!signingBlock.test(gradle)) {
      throw new Error('with-release-signing: no signingConfigs block in app/build.gradle');
    }
    gradle = gradle.replace(signingBlock, (m) => m + RELEASE_CONFIG);

    // 2. Point the release build type at it when present.
    const releaseType = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig signingConfigs\.debug/;
    if (!releaseType.test(gradle)) {
      throw new Error('with-release-signing: release build type not found in app/build.gradle');
    }
    gradle = gradle.replace(
      releaseType,
      '$1signingConfig System.getenv("CM_KEYSTORE_PATH") ? signingConfigs.release : signingConfigs.debug',
    );

    mod.modResults.contents = gradle;
    return mod;
  });
};
